CREATE TABLE statut (
  id_statut int(11) NOT NULL,
  nom varchar(50) NOT NULL,
  description varchar(50) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE talents (
  id_talent int(11) NOT NULL,
  nom varchar(50) NOT NULL,
  description_talent varchar(10000) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

INSERT INTO talents (id_talent, nom, description_talent) VALUES
(1, 'Absentéisme', 'Le Pokémon n\'a pas la possibilité d\'attaquer un tour sur deux.'),
(2, 'Absorbe-Eau', 'Immunité contre les capacités de type Eau : elles soignent jusqu\'à 25 % des PV maximum du Pokémon.'),
(3, 'Absorbe-Volt', 'Immunité contre les capacités de type Électrik : elles soignent jusqu\'à 25 % des PV maximum du Pokémon.'),
(4,'Agitation', 'La statistique d\'Attaque du Pokémon augmente de 50 %. Les capacités physiques du Pokémon ont leur Précision diminuée de 20 %.'),
(5, 'Air Lock', 'Annule les effets du climat.'),
(6,'Anti-Bruit', 'Immunité contre les capacités sonores.'),
(7,'Armumagma', 'Immunité contre le statut gel.'),
(8,'Armurbaston', 'Les coups critiques sont impossibles pour le Pokémon ennemi.'),
(9,'Attention', 'Immunité contre la peur et contre l\'intimidation.'),
(10,'Benêt', 'Immunité contre l\'attraction, contre la provocation et contre l\'intimidation.'),
(11,'Brasier', 'Augmente la puissance des capacités de type Feu lorsque le Pokémon a moins d\'1/3 de ses PV.'),
(12,'Calque', 'Change le talent du Pokémon en celui d\'un Pokémon adverse.'),
(13,'Chlorophylle', 'Sous le climat soleil, la Vitesse du Pokémon est doublée.'),
(14,'Ciel Gris', 'Annule les effets du climat.'),
(15,'Coloforce', 'La statistique d\'Attaque du Pokémon est doublée.'),
(16,'Coque Armure', 'Les coups critiques sont impossibles pour le Pokémon ennemi.'),
(17,'Corps Ardent', 'Les capacités directes reçues ont 30 % de chances de donner le statut brûlure à leur lanceur.'),
(18,'Corps Sain', 'Immunité contre la diminution de statistiques du Pokémon imposée par un autre.'),
(19,'Crachin','Active le climat pluie lorsque le Pokémon est envoyé au combat.'),
(20,'Cran', 'Avec un statut altéré, l\'Attaque du Pokémon augmente de 50 %.Immunité contre la diminution de l\'Attaque du Pokémon imposée par le statut brûlure.'),
(21,'Cuvette', 'Sous le climat pluie, le Pokémon régénère 1/16 de ses PV maximum à chaque fin de tour.'),
(22,'Homochromie','Change le type du Pokémon en celui de la dernière capacité offensive subie.'),
(23,'Écaille Spéciale','Avec un statut altéré, la Défense du Pokémon augmente de 50 %.'),
(24,'Échauffement','Immunité contre le statut paralysie.'),
(25,'Écran Fumée','Immunité contre la diminution de statistiques du Pokémon imposée par un autre.'),
(26,'Écran Poudre','Les effets secondaires des capacités ennemies sont annulés.'),
(27,'Engrais','Augmente la puissance des capacités de type Plante lorsque le Pokémon a moins d\'1/3 de ses PV.'),
(28,'Esprit Vital','Immunité contre le statut sommeil.'),
(29,'Essaim','Augmente la puissance des capacités de type Insecte lorsque le Pokémon a moins d\'1/3 de ses PV.'),
(30,'Fermeté','Immunité contre les capacités OHKO : le Pokémon résistera et gardera 1 PV s\'il avait tous ses PV avant l\'attaque.'),
(31,'Force Pure','La statistique d\'Attaque du Pokémon est doublée.'),
(32,'Fuite','La fuite du Pokémon contre un Pokémon sauvage est garantie.'),
(33,'Garde Mystik','Immunité contre les capacités offensives qui ne sont pas super efficaces, sauf Lutte.'),
(34,'Glissade','Sous le climat pluie, la Vitesse du Pokémon est doublée.'),
(35,'Glu','L\'objet tenu ne peut pas être perdu.'),
(36,'Hyper Cutter','Immunité contre la diminution de l\'Attaque du Pokémon.'),
(37,'Ignifu-Voile','Immunité contre le statut brûlure.'),
(38,'Insomnia','Immunité contre le statut sommeil.'),
(39,'Intimidation','La statistique d\'Attaque du Pokémon adverse baisse lorsque le Pokémon est envoyé au combat.'),
(40,'Isograisse','Diminue les dégâts subits par les capacités de type Feu et de type Glace.'),
(41,'Joli Sourire','Les capacités directes reçues ont 30 % de chances de donner le statut attraction à leur lanceur de sexe opposé.'),
(42,'Lévitation','Immunité contre les capacités de type Sol. Immunité contre les champs. Immunité contre Fertilisation, Picots, Pics Toxik, Piège Sable et Toile Gluante.'),
(43,'Luminescence','Permet au Pokémon ayant le talent d\'ignorer les augmentations d\'Esquive de sa cible, et de l\'immuniser aux baisses de sa Précision.'),
(44,'Magnépiège','La fuite ou le switch d\'un Pokémon adverse de type Acier est impossible.'),
(45,'Marque Ombre','La fuite ou le switch d\'un Pokémon adverse est impossible.'),
(46,'Matinal','Le Pokémon se réveille deux fois plus rapidement.'),
(47,'Médic Nature','Le Pokémon soigne ses altérations de statut s\'il switch ou en fin de combat.'),
(48,'Météo','Change la forme de Morphéo selon le climat.'),
(49,'Moins','La statistique d\'Attaque Spéciale du Pokémon augmente de 50 % si un allié en Combat Duo a le talent Plus ou Moins.'),
(50,'Moiteur','Le Pokémon adverse n\'a pas la possibilité d\'utiliser une capacité auto-destructrice.'),
(51,'Mue','Le Pokémon soigne ses altérations de statut à chaque tour. (1 chance sur 3)'),
(52,'Œil Composé','La statistique de Précision du Pokémon augmente de 30 %.'),
(53,'Paratonnerre','Immunité contre les capacités de type Électrik : elles augmentent d\'un niveau l\'Attaque Spéciale du Pokémon. Les capacités de type Électrik utilisées par un Pokémon adjacent touchent obligatoirement ce Pokémon.'),
(54,'Peau Dure','Les capacités directes reçues font perdre 1/8 des PV maximum du lanceur.'),
(55,'Piège Sable','La fuite ou le switch d\'un Pokémon adverse ne volant pas est impossible.'),
(56,'Plus','La statistique d\'Attaque Spéciale du Pokémon augmente de 50 % si un allié en Combat Duo a le talent Plus ou Moins.'),
(57,'Point Poison','Les capacités directes reçues ont 30 % de chances de donner le statut poison à leur lanceur.'),
(58,'Pose Spore','Les capacités directes reçues ont 30 % de chances de donner le statut poison, paralysie ou sommeil à leur lanceur.'),
(59,'Pression','Le Pokémon adverse consomme deux fois plus de PP lorsqu\'il utilise une capacité offensive.'),
(60,'Puanteur','Les capacités physiques du Pokémon ont 10 % de chances d\'apeurer la cible.'),
(61,'Ramassage','Après un combat, le Pokémon a une chance de ramasser un objet.'),
(62,'Regard Vif','Immunité contre la diminution de la Précision du Pokémon.'),
(63,'Sable Volant','Active le climat tempête de sable lorsque le Pokémon est envoyé au combat.'),
(64,'Sécheresse','Active le climat soleil lorsque le Pokémon est envoyé au combat.'),
(65,'Sérénité','Les effets secondaires des capacités du Pokémon ont leurs chances doublées.'),
(66,'Statik','Les capacités directes reçues ont 30 % de chances de donner le statut paralysie à leur lanceur.'),
(67,'Suintement','Inflige des dégâts au lieu de redonner des PV lorsque le Pokémon adverse utilise une capacité drainant des PV.'),
(68,'Synchro','Le Pokémon adverse obtient la brûlure, l\'empoisonnement ou la paralysie subie par le Pokémon.'),
(69,'Tempo Perso','Immunité contre la confusion et contre l\'intimidation.'),
(70,'Tête de Roc','Immunité contre le contrecoup.'),
(71,'Torche','Immunité contre les capacités de type Feu : elles augmentent de 50 % la puissance des capacités de type Feu du Pokémon.'),
(72,'Torrent','Augmente la puissance des capacités de type Eau lorsque le Pokémon a moins d\'1/3 de ses PV.'),
(73,'Turbo','La statistique de Vitesse du Pokémon augmente d\'un niveau à chaque tour.'),
(74,'Vaccin','Immunité contre le statut poison.'),
(75,'Ventouse','Immunité contre le switch forcé.'),
(76,'Voile Sable','Sous le climat tempête de sable, l\'Esquive du Pokémon augmente de 20 %. Immunité contre les dégâts de la tempête de sable.'),
(77,'Adaptabilité','Augmente la puissance des capacités STAB.'),
(78,'Alerte Neige','Active le climat grêle lorsque le Pokémon est envoyé au combat.'),
(79,'Annule Garde','Les capacités du Pokémon et de l\'adversaire ne peuvent pas échouer.'),
(80,'Anticipation','Détecte si le Pokémon adverse possède des capacités efficaces sur le Pokémon, des capacités OHKO ou les capacités Explosion et Destruction.'),
(81,'Boom Final','Les capacités directes reçues mettant K.O. le Pokémon font perdre 25 % des PV maximum du lanceur.'),
(82,'Brise Moule','Ignore les talents adverses ayant un effet sur les capacités du Pokémon.'),
(83,'Chanceux','Les coups critiques du Pokémon ont une chance doublée.'),
(84,'Cherche Miel','Après un combat, le Pokémon a une chance de ramasser du Miel.'),
(85,'Colérique','La statistique d\'Attaque du Pokémon augmente de six niveaux s\'il est touché par un coup critique.'),
(86,'Corps Gel','Sous le climat grêle, le Pokémon régénère 1/16 de ses PV maximum à chaque fin de tour. Immunité contre les dégâts de la grêle.'),
(87,'Début Calme','La statistique d\'Attaque et de Vitesse du Pokémon sont divisées par deux pendant 5 tours.'),
(88,'Délestage','La statistique de Vitesse du Pokémon est doublée s\'il n\'a plus d\'objet tenu.'),
(89,'Don Floral','Sous le climat soleil, l\'Attaque et la Défense Spéciale du Pokémon et de ses alliés augmentent de 50 %. Change la forme de Ceriflor selon le climat.'),
(90,'Feuille Garde','Sous le climat soleil, soigne le Pokémon des altériations de statut futures.'),
(91,'Filtre','Diminue les dégâts subits par les capacités super efficaces.'),
(92,'Force Soleil','Sous le climat soleil, l\'Attaque Spéciale du Pokémon augmente de 50 % mais il perd 1/8 de ses PV maximum à chaque fin de tour.'),
(93,'Fouille','Détecte l\'objet tenu par le Pokémon adverse.'),
(94,'Frein','Le Pokémon n\'a pas la possibilité d\'attaquer en premier s\'il n\'a pas la priorité.'),
(95,'Garde Magik','Immunité contre toutes les capacités qui ne sont pas directes.'),
(96,'Gloutonnerie','La Baie tenue peut être consommée lorsque les PV descendent en dessous de 50 % au lieu de 25 %.'),
(97,'Hydratation','Sous le climat pluie, soigne le Pokémon des altériations de statut passées et futures.'),
(98,'Ignifugé','Diminue les dégâts subits par les capacités de type Feu et par les effets de brûlure.'),
(99,'Impassible','Avec un statut apeuré, la Vitesse du Pokémon augmente d\'un niveau.'),
(100,'Inconscient','Ignore les améliorations de statistiques du Pokémon adverse, à l\'exception de sa Vitesse.'),
(101,'Lavabo','Immunité contre les capacités de type Eau : elles augmentent d\'un niveau l\'Attaque Spéciale du Pokémon. Les capacités de type Eau utilisées par un Pokémon adjacent touchent obligatoirement ce Pokémon.'),
(102,'Lentiteintée','Augmente la puissance des capacités peu efficaces sur le Pokémon adverse.'),
(103,'Maladresse','L\'objet tenu ne peut pas être utilisé.'),
(104,'Mauvais Rêve','Inflige 1/8e de ses PV au Pokémon adverse s\'il est endormi.'),
(105,'Motorisé','Immunité contre les capacités de type Électrik : elles augmentent d\'un niveau la Vitesse du Pokémon.'),
(106,'Multi-Coups','Les capacités du Pokémon frappent toujours le nombre de coups maximum.'),
(107,'Multi-Type','Change la forme d\'Arceus selon la Plaque tenue.'),
(108,'Normalise','Change le type des capacités du Pokémon et les considère comme étant de type Normal.'),
(109,'Peau Sèche','Sous le climat soleil, le Pokémon perd 1/8 de ses PV maximum à chaque fin de tour. Sous le climat pluie, le Pokémon régénère 1/8 de ses PV maximum à chaque fin de tour. Les capacités de type Feu infligent 25 % de dégâts supplémentaires au Pokémon. Immunité contre les capacités de type Eau : elles soignent jusqu\'à 25 % des PV maximum du Pokémon.'),
(110,'Pied Confus','Avec un statut confus, l\'Esquive du Pokémon augmente de 50 %.'),
(111,'Pied Véloce','Avec un statut altéré, la Vitesse du Pokémon augmente de 50 %. Immunité contre la diminution de la Vitesse du Pokémon imposée par le statut paralysie.'),
(112,'Poing de Fer','Augmente la puissance des capacités coups de poing.'),
(113,'Prédiction','Détecte la capacité la plus puissante du Pokémon adverse.'),
(114,'Querelleur','Ignore les immunités du type Spectre du Pokémon adverse. Il devient donc possible de toucher un Pokémon de ce type avec des capacités de type Normal ou Combat.'),
(115,'Rideau Neige','Sous le climat grêle, l\'Esquive du Pokémon augmente de 20 %. Immunité contre les dégâts de la grêle.'),
(116,'Rivalité','Augmente la puissance des capacités si le Pokémon adverse est du même sexe, mais la diminue s\'il est du sexe opposé.'),
(117,'Simple','Les effets des modifications de statistiques du Pokémon sont doublés, qu\'ils soient positifs ou négatifs.'),
(118,'Sniper','Les coups critiques du Pokémon ont une puissance triplée.'),
(119,'Soin Poison','Avec un statut empoisonné ou gravement empoisonné, le Pokémon régénère 1/8 de ses PV maximum au lieu d\'en perdre.'),
(120,'Solide Roc','Diminue les dégâts subits par les capacités super efficaces.'),
(121,'Technicien','Augmente la puissance des capacités infligeant. 60 dégâts ou moins.'),
(122,'Télécharge','Augmente soit l\'Attaque, soit l\'Attaque Spéciale en fonction de la statistique de défense la plus faible du Pokémon adverse.'),
(123,'Téméraire','Augmente la puissance des capacités à contrecoup, sauf Lutte.'),
(124,'Acharné','La statistique d\'Attaque du Pokémon augmente de deux niveaux s\'il subit une diminution de statistiques par un adversaire.'),
(125,'Analyste','Augmente la puissance des capacités si le Pokémon frappe en dernier durant le tour.'),
(126,'Armurouillée','La statistique de Défense du Pokémon diminue d\'un niveau et sa Vitesse augmente de deux lorsqu\'il est touché par une capacité physique.'),
(127,'Baigne Sable','Sous le climat tempête de sable, la Vitesse du Pokémon est doublée. Immunité contre les dégâts de la tempête de sable.'),
(128,'Cœur de Coq','Immunité contre la diminution de la Défense du Pokémon.'),
(129,'Cœur Noble','La statistique d\'Attaque du Pokémon augmente d\'un niveau s\'il est touché par une capacité de type Ténèbres.'),
(130,'Cœur Soin','Le Pokémon soigne les altérations de statut d\'un allié adjacent. (30 % de chance)'),
(131,'Contestation','Les effets des changements de statistiques sont inversés.'),
(132,'Corps Maudit','Les capacités du Pokémon adverse ont 30 % de chances de s\'entraver.'),
(133,'Défaitiste','La statistique d\'Attaque et d\'Attaque Spéciale du Pokémon sont divisées par deux s\'il a moins de 50 % de ses PV.'),
(134,'Envelocape','Immunité contre les dégâts de la grêle et de la tempête de sable. Immunité contre les capacités poudreuses et le talent Pose Spore.'),
(135,'Épine de Fer','Les capacités directes reçues font perdre 1/8 des PV maximum du lanceur.'),
(136,'Farceur','La priorité des capacités de statut augmente d\'un niveau.'),
(137,'Force Sable','Sous le climat tempête de sable, la puissance des capacités de type Acier, Roche et Sol du Pokémon augmente de 30 %. Immunité contre les dégâts de la tempête de sable.'),
(138,'Garde-Ami','Diminue les dégâts subits par les alliés.'),
(139,'Heavy Metal','Le poids du Pokémon est doublé.'),
(140,'Herbivore','Immunité contre les capacités de type Plante : elles augmentent d\'un niveau l\'Attaque du Pokémon.'),
(141,'Illusion','Change l\'apparence du Pokémon en celle du dernier Pokémon de l\'équipe lorsque le Pokémon est envoyé au combat.'),
(142,'Imposteur','Transforme le Pokémon de façon à imiter le Pokémon adverse lors de son entrée au combat.'),
(143,'Impudence','La statistique d\'Attaque du Pokémon augmente d\'un niveau s\'il met un Pokémon K.O.'),
(144,'Infiltration','Ignore les capacités de protection adverses, sauf Détection et Abri.'),
(145,'Light Metal','Le poids du Pokémon est divisé par deux.'),
(146,'Lunatique','Augmente aléatoirement une statistique du Pokémon de deux niveaux et en baisse une autre d\'un niveau à chaque tour. La Précision et l\'Esquive sont comprises.'),
(147,'Miroir Magik','Les capacités de statut sont retournées contre le Pokémon adverse.'),
(148,'Mode Transe','Change la forme de Darumacho si ses PV sont inférieurs à 50 % du maximum.'),
(149,'Momie','Remplace le talent de l\'adversaire attaquant par Momie lorsque le détenteur subit une attaque directe.'),
(150,'Multiécaille','Diminue les dégâts subits par les capacités offensives si le Pokémon a tous ses PV.'),
(151,'Peau Miracle','Les capacités de statut du Pokémon adverse ont une chance sur deux d\'échouer.'),
(152,'Phobique','La statistique de Vitesse du Pokémon augmente d\'un niveau s\'il est touché par une capacité de type Insecte, Spectre ou Ténèbres.'),
(153,'Pickpocket','Les capacités directes reçues font voler au Pokémon l\'objet tenu du lanceur.'),
(154,'Rage Brûlure','La statistique d\'Attaque Spéciale du Pokémon augmente de 50 % s\'il est brûlé.'),
(155,'Rage Poison','La statistique d\'Attaque du Pokémon augmente de 50 % s\'il est empoisonné.'),
(156,'Récolte','La Baie consommée a 50 % de chances d\'être récupérée à la fin du tour.'),
(157,'Régé-Force','Le Pokémon soigne 1/3 de ses PV s\'il switch.'),
(158,'Sans Limite','Augmente la puissance des capacités pouvant avoir un effet secondaire, mais annule ce dernier.'),
(159,'Télépathe','Immunité contre les capacités des alliés en Combat Duo ou Trio.'),
(160,'Tension','La Baie tenue par le Pokémon adverse ne peut pas être consommée tant que le Pokémon est sur le terrain.'),
(161,'Téra-Voltage','Ignore les talents adverses ayant un effet sur les capacités du Pokémon.'),
(162,'Toxitouche','Les capacités directes envoyées ont 30 % de chances de donner le statut poison à leur cible.'),
(163,'Turbo Brasier','Ignore les talents adverses ayant un effet sur les capacités du Pokémon.'),
(164,'Victorieux','La statistique de Précision du Pokémon et de ses alliés augmente de 10 %.'),
(165,'Ailes Bourrasque','La priorité des capacités de type Vol augmente d\'un niveau.'),
(166,'Amour Filial','Les capacités du Pokémon frappe deux fois par tour au lieu d\'un, mais le deuxième coup fait deux fois moins de dégâts que le premier.'),
(167,'Aroma-Voile','Immunité contre les attaques limitant le choix des capacités pour le Pokémon et ses alliés sur le terrain.'),
(168,'Aura Féérique','Augmente la puissance des capacités de type Fée.'),
(169,'Aura Inversée','Diminue la puissance des capacités de type Fée quand Aura Féérique est actif. Diminue la puissance des capacités de type Ténèbres quand Aura Ténébreuse est actif.'),
(170,'Aura Ténébreuse','Augmente la puissance des capacités de type Ténèbres.'),
(171,'Bajoues','La Baie tenue permet aussi de récupérer 1/3 de ses PV totaux.'),
(172,'Battant','La statistique d\'Attaque Spéciale du Pokémon augmente de deux niveaux s\'il subit une diminution de statistiques par un adversaire.'),
(173,'Déclic Tactique','Change la forme d\'Exagide selon les capacités qu\'il utilise.'),
(174,'Flora-Voile','Immunité contre la diminution de statistiques du Pokémon et des alliés de type Plante imposée par un autre.'),
(175,'Gluco-Voile','Immunité contre le statut sommeil pour le Pokémon et ses alliés.'),
(176,'Griffe Dure','Les capacités directes utilisées par le Pokémon infligent 30 % de dégâts supplémentaires.'),
(177,'Magicien','L\'objet tenu par le Pokémon adverse est volé lorsque le Pokémon le touche avec une capacité directe.'),
(178,'Méga Blaster','Augmente la puissance des capacités d\'aura.'),
(179,'Pare-Balles','Immunité contre les capacités à projectiles.'),
(180,'Peau Céleste','Change le type des capacités de type Normal du Pokémon et les considère comme étant de type Vol. Augmente la puissance de ces capacités.'),
(181,'Peau Féérique','Change le type des capacités de type Normal du Pokémon et les considère comme étant de type Fée. Augmente la puissance de ces capacités.'),
(182,'Peau Gelée','Change le type des capacités de type Normal du Pokémon et les considère comme étant de type Glace. Augmente la puissance de ces capacités.'),
(183,'Poisseux','Les capacités directes reçues font diminuer la Vitesse du lanceur.'),
(184,'Prognathe','Augmente la puissance des capacités à base de morsures.'),
(185,'Protéen','Change le type du Pokémon en celui de toute capacité qu\'il utilise.'),
(186,'Symbiose','L\'objet tenu est donné à l\'allié lorsque ce dernier utilise le sien.'),
(187,'Toison Épaisse','La statistique de Défense du Pokémon est doublée.'),
(188,'Toison Herbue','Sous un Champ Herbu, la Défense du Pokémon augmente de 50 %.'),
(189,'Mer Primaire','Active le climat pluie battante lorsque le Pokémon est envoyé au combat.'),
(190,'Souffle Delta','Active le climat vent mystérieux lorsque le Pokémon est envoyé au combat.'),
(191,'Terre Finale','Active le climat soleil intense lorsque le Pokémon est envoyé au combat.'),
(192,'Animacœur','La statistique d\'Attaque Spéciale du Pokémon augmente d\'un niveau si un Pokémon est mis K.O.'),
(193,'Aquabulle','Diminue les dégâts subits par les capacités de type Feu. Augmente la puissance des capacités de type Eau. Immunité au statut brûlure.'),
(194,'Banc','Change la forme de Froussardine si ses PV sont supérieurs à 25 % du maximum.'),
(195,'Batterie','Augmente la puissance des capacités spéciales des alliés.'),
(196,'Boost Chimère','La statistique la plus élevée du Pokémon augmente d\'un niveau s\'il met un Pokémon K.O.'),
(197,'Bouclier-Carcan','Change la forme de Météno lorsque ses PV descendent sous les 50 %. Immunité aux capacités de statut lorsqu\'il est sous sa forme Météore. Il perd cette immunité lorsqu\'il change de forme.'),
(198,'Boule de Poils','Diminue les dégâts subits par les capacités directes qui ne sont pas de type Feu. Augmente les dégâts subits par les capacités de type Feu.'),
(199,'Chasse-Neige','Sous le climat grêle, la Vitesse du Pokémon est doublée.'),
(200,'Corps Coloré','Le Pokémon adverse n\'a pas la possibilité d\'utiliser une capacité de priorité.'),
(201,'Corrosion','Ignore l\'immunité à l\'empoisonnement des types Acier et Poison.'),
(202,'Créa-Brume','Active un Champ Brumeux lorsque le Pokémon est envoyé au combat.'),
(203,'Créa-Élec','Active un Champ Électrifié lorsque le Pokémon est envoyé au combat.'),
(204,'Créa-Herbe','Active un Champ Herbu lorsque le Pokémon est envoyé au combat.'),
(205,'Créa-Psy','Active un Champ Psychique lorsque le Pokémon est envoyé au combat.'),
(206,'Cruauté','Les coups critiques sont systémiques contre un ennemi empoisonné.'),
(207,'Danseuse','Permet d\'utiliser les capacités de danse utilisées par les autres Pokémon.'),
(208,'Endurance','La statistique de Défense du Pokémon augmente d\'un niveau s\'il est touché par une capacité offensive.'),
(209,'Escampette','La fuite ou le switch du Pokémon est automatique s\'il a moins de 50 % de ses PV.'),
(210,'Expert Acier','Augmente la puissance des capacités de type Acier.'),
(211,'Expuls\'Organes','Inflige à l\'adversaire des dégâts équivalents au nombre de PV qu\'il restait au Pokémon avant d\'être mis K.O.'),
(212,'Fantômasque','Change la forme de Mimiqui après les premiers dégâts encaissés.'),
(213,'Filature','Augmente la puissance des capacités des Pokémon arrivant au milieu d\'un combat.'),
(214,'Folle Furie','La statistique d\'Attaque Spéciale du Pokémon augmente d\'un niveau s\'il passe en dessous de 50 % de ses PV.'),
(215,'Hydrata-Son','Les capacités sonores du Pokémon deviennent de type Eau.'),
(216,'Hypersommeil','Immunité contre les statuts, sauf le sommeil, car le Pokémon est endormi en tout temps. Il peut attaquer normalement malgré cela.'),
(217,'Longue Portée','Les capacités du Pokémon sont toutes considérées comme étant sans contact.'),
(218,'Mèche Rebelle','La statistique de Vitesse de l\'attaquant diminue lorsque le Pokémon subit une attaque directe.'),
(219,'Métallo-Garde','Immunité contre la diminution de statistiques du Pokémon imposée par un autre.'),
(220,'Osmose','Change le talent du Pokémon en celui d\'un allié mis K.O.'),
(221,'Peau Électrique','Change le type des capacités de type Normal du Pokémon et les considère comme étant de type Électrik. Augmente la puissance de ces capacités.'),
(222,'Prestance Royale','Le Pokémon adverse n\'a pas la possibilité d\'utiliser une capacité de priorité.'),
(223,'Prioguérison','La priorité des capacités de soin augmente de trois niveaux.'),
(224,'Prisme-Armure','Diminue les dégâts subits par les capacités super efficaces.'),
(225,'Rassemblement','Change la forme de Zygarde si ses PV sont inférieurs à 50 % du maximum.'),
(226,'Receveur','Change le talent du Pokémon en celui d\'un allié mis K.O.'),
(227,'Repli Tactique','La fuite ou le switch du Pokémon est automatique s\'il a moins de 50 % de ses PV.'),
(228,'Sable Humide','La statistique de Défense du Pokémon augmente de deux niveaux s\'il est touché par une capacité de type Eau.'),
(229,'Spectro-Bouclier','Diminue les dégâts subits par les capacités offensives si le Pokémon a tous ses PV.'),
(230,'Surf Caudal','Sous un Champ Électrifié, la Vitesse du Pokémon est doublée.'),
(231,'Synergie','Change la forme d\'Amphinobi après avoir vaincu un adversaire.'),
(232,'Système Alpha','Change la forme de Silvallié selon la ROM tenue.'),
(233,'Cérébro-Force','Augmente la puissance des capacités super efficaces.'),
(234,'Âme Vagabonde','Remplace le talent du Pokémon adverse par Âme Vagabonde et prend possession de son ancien lorsque le Pokémon subit une capacité directe.'),
(235,'Armure Miroir','Les effets réducteurs de statistiques sont renvoyés au Pokémon adverse.'),
(236,'Boost Acier','Augmente la puissance des capacités de type Acier du Pokémon et de ses alliés.'),
(237,'Brise-Barrière','Annule les effets de Mur Lumière, Protection et Voile Aurore pour tous les Pokémon lorsque le Pokémon est envoyé au combat.'),
(238,'Cercle d\'Énergie','Augmente la puissance des capacités des alliés du Pokémon se trouvant sur le terrain.'),
(239,'Corps Condamné','Force le Pokémon et l\'adversaire à tomber K.O. trois tours après que le Pokémon a été touché par une capacité directe, à moins qu\'ils ne soient remplacés entre temps.'),
(240,'Déclic Fringale','Change la forme de Morpeko entre chaque tour. Change le type de Roue Libre entre chaque tour.'),
(241,'Dégobage','Change la forme de Nigosier lorsqu\'il utilise la capacité Surf ou Plongée. S\'il subit des dégâts par la suite, il recrache ce qu\'il a dans le bec sur le Pokémon adverse.'),
(242,'Écailles Glacées','Diminue les dégâts subits par les capacités spéciales.'),
(243,'Effilochage','La statistique de Vitesse du Pokémon adverse diminue lorsque le Pokémon est touché par une capacité.'),
(244,'Égide Inflexible','La statistique de Défense du Pokémon augmente d\'un niveau en entrant sur le terrain.'),
(245,'Entêtement','La statistique d\'Attaque est augmentée, mais il devient impossible d\'utiliser toute autre capacité que celle utilisée en premier par le Pokémon.'),
(246,'Expul\'Sable','Active le climat tempête de sable lorsque le Pokémon est touché par une capacité offensive.'),
(247,'Gaz Inhibiteur','Annule les effets des talents des autres Pokémon.'),
(248,'Lame Indomptable','La statistique d\'Attaque du Pokémon augmente d\'un niveau en entrant sur le terrain.'),
(249,'Libéro','Change le type du Pokémon en celui de toute capacité qu\'il utilise.'),
(250,'Mimétisme','Change le type du Pokémon en celui du champ actif.'),
(251,'Mûrissement','La Baie tenue a un effet doublé.'),
(252,'Nerfs d\'Acier','Ignore les effets des capacités ou des talents attirant les capacités.'),
(253,'Propulseur','Ignore les effets des capacités ou des talents attirant les capacités.'),
(254,'Punk Rock','Augmente la puissance des capacités sonores. Le Pokémon ne subit que la moitié des dégâts quand il est touché par ce genre de capacités.'),
(255,'Ramasse Ball','L\'objet Ball peut être récupéré si le Dresseur rate la capture d\'un Pokémon sauvage et que le Pokémon ne tient pas d\'objet. N\'affecte que la première Ball perdue.'),
(256,'Tête de Gel','Change la forme de Bekaglaçon après les premiers dégâts physiques encaissés. Rechange la forme de Bekaglaçon s\'il grêle.'),
(257,'Turbine','La statistique de Vitesse du Pokémon augmente de six niveaux s\'il est touché par une capacité de type Feu ou Eau.'),
(258,'Voile Pastel','Immunité contre l\'empoisonnement pour le Pokémon et ses alliés sur le terrain.'),
(259,'Poing Invisible','Ignore les effets d\'Abri et de ses équivalents (sauf Gardomax) si la capacité utilisée est physique.'),
(260,'Tir Vif','Les capacités du Pokémon ont 20 % de chances d\'être prioritaires.'),
(261,'Blanche Ruade','La statistique d\'Attaque du Pokémon augmente d\'un niveau s\'il met un Pokémon K.O.'),
(262,'Breuvage Suspect','Annule tous les changements de statistiques des alliés lorsque le Pokémon est envoyé au combat.'),
(263,'Dent de Dragon','Augmente la puissance des capacités de type Dragon.'),
(264,'Osmose Équine','Combine les talents Tension et Blanche Ruade. (Sylveroy, le Cavalier du Froid). Combine les talents Tension et Sombre Ruade. (Sylveroy, le Cavalier d\'Effroi)'),
(265,'Sombre Ruade','La statistique d\'Attaque Spéciale du Pokémon augmente d\'un niveau s\'il met un Pokémon K.O.'),
(266,'Transistor','Augmente la puissance des capacités de type Électrik.'),
(267,'Absorbe-Terre','Immunité contre les capacités de type Sol : elles soignent jusqu\'à 25 % des PV maximum du Pokémon.'),
(268,'Aéroporté','La statistique d\'Attaque du Pokémon augmente si un vent arrière souffle ou s\'il est touché par une capacité faisant appel au vent. Dans ce dernier cas, il ne subit aucun dégât.'),
(269,'Armure Caudale','Immunité contre les capacités prioritaires.'),
(270,'Bien Cuit','Immunité contre les capacités de type Feu : elles augmentent beaucoup la Défense du Pokémon.'),
(271,'Bois du Fléau','La statistique d\'Attaque de tous les autres Pokémon diminue lorsque le Pokémon est envoyé au combat.'),
(272,'Charge Quantique','La statistique la plus élevée du Pokémon augmente quand un Champ Électrifié est actif ou qu\'une capsule d\'Énergie Booster est tenue.'),
(273,'Chien de Garde','mmunité contre les capacités ou objets faisant changer de Pokémon. Immunité contre le talent Intimidation : la statistique d\'Attaque augmente au lieu de diminuer.'),
(274,'Collab','Copie les changements de statistiques de l\'allié lorsque le Pokémon est envoyé au combat.'),
(275,'Commandant','Augmente toutes les statistiques de deux niveaux d\'un Oyacata allié se trouvant sur le terrain lorsque le Pokémon est envoyé au combat. Le Pokémon entre dans sa bouche.'),
(276,'Corps en Or','Immunité contre les capacités de statut.'),
(277,'Courroupace','La statistique de Défense et de Défense Spéciale diminuent, mais la statistique d\'Attaque, d\'Attaque Spéciale et de Vitesse augmentent si le Pokémon a moins de la moitié de ses PV après avoir subi une attaque.'),
(278,'Dépôt Toxique','Pose des pics toxiques dans le camp adverse lorsque le Pokémon est touché par une capacité physique.'),
(279,'Épée du Fléau','La statistique de Défense de tous les autres Pokémon diminue lorsque le Pokémon est envoyé au combat.'),
(280,'Force Fongique','Ignore les talents adverses, mais le Pokémon agit toujours plus lentement quand il utilise une capacité de statut.'),
(281,'Général Suprême','La statistique d\'Attaque et d\'Attaque Spéciale augmentent de 10 % pour chaque allié mis K.O. avant l\'arrivée du Pokémon sur le terrain.'),
(282,'Grecharge','Augmente la puissance de la prochaine capacité de type Électrik lorsque le Pokémon subit des dégâts.'),
(283,'Incisif','Augmente la puissance des capacités tranchantes.'),
(284,'Moteur à Hadrons','Active un Champ Électrifié lorsque le Pokémon est envoyé au combat. La statistique d\'Attaque Spéciale augmente si un Champ Électrifié est déjà actif.'),
(285,'Odeur Tenace','Remplace le talent de l\'adversaire attaquant par Odeur Tenace lorsque le Pokémon subit une attaque directe.'),
(286,'Opportuniste','Augmente les statistiques du Pokémon de la même manière que le Pokémon adverse.'),
(287,'Paléosynthèse','La statistique la plus élevée du Pokémon augmente quand le soleil brille ou qu\'une capsule d\'Énergie Booster est tenue.'),
(288,'Perles du Fléau','La statistique de Défense Spéciale de tous les autres Pokémon diminue lorsque le Pokémon est envoyé au combat.'),
(289,'Porte-Roche','Augmente la puissance des capacités de type Roche.'),
(290,'Pouls Orichalque','Active le climat soleil lorsque le Pokémon est envoyé au combat. La statistique d\'Attaque augmente si le climat est déjà ensoleillé.'),
(291,'Ruminant','La Baie tenue peut être consommée une deuxième fois à la fin du tour suivant.'),
(292,'Sel Purificateur','Immunité contre les altérations de statut. Diminue de moitié les dégâts des capacités de type Spectre.'),
(293,'Semencier','Active un Champ Herbu lorsque le Pokémon subit une attaque.'),
(294,'Supermutation','Change la forme de Superdofin lorsqu\'il est retiré du combat.'),
(295,'Thermodynamique','Immunité contre les capacités de type Feu : elles augmentent l\'Attaque du Pokémon.'),
(296,'Turbine Éolienne','Augmente la puissance de la prochaine capacité de type Électrik lorsque le Pokémon est touché par une capacité faisant appel au vent.'),
(297,'Urne du Fléau','La statistique d\'Attaque Spéciale de tous les autres Pokémon diminue lorsque le Pokémon est envoyé au combat.'),
(298,'Aux Petits Soins','Lorsqu\'il entre en combat, le Pokémon restaure les PV d\'un allié.'),
(299,'Chaîne Toxique','Les capacités directes lancées ont 30 % de chances de donner le statut empoisonnement grave à la cible.'),
(300,'Force Mémorielle','Une statistique augmente d\'un cran lors de la téracristalisation selon le masque du Pokémon.'),
(301,'Nectar Mielleux','La statistique d\'Esquive des Pokémon adverses diminue lorsque le Pokémon est envoyé au combat.'),
(302,'Œil Révélateur','Ignore les immunités du type Spectre et les changements d\'Esquive du Pokémon adverse. Empêche aussi les diminutions de Précision du Pokémon.'),
(303,'Téramorphose','Transforme le Pokémon en sa forme Téracristal quand il entre en combat.'),
(304,'Emprise Toxique','Lorsqu'un Pokémon est empoisonné par l'une des capacités de Pêchaminus, Emprise Toxique le rend également confus.');

